catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') return;

    var ga = new GlideAjax('x_1216348_claim_0.getEmpDet');
    ga.addParam('sysparm_name', 'getEmpInfo');
    ga.addParam('sysparm_empnum', newValue);
    // alert(newValue);

    ga.getXML(getEmpDetails);

    function getEmpDetails(response) {
        var data = response.responseXML.documentElement.getAttribute("answer");
        // alert(data);
        var ans = JSON.parse(data);
        if (ans) {
            //alert('Inside If');
            g_form.setValue('full_name', ans.full_name+'');
            g_form.setValue('email', ans.email+'');
			g_form.setValue('contact_no',ans.contact_no);
			//g_form.setvalue('document_date',ans.document_date);
			g_form.setValue('account_name',ans.account_name);
			g_form.setValue('account_number',ans.account_number);
			g_form.setValue('bank_name',ans.bank_name);
			g_form.setValue('ifsc_code',ans.ifsc_code);



        }
    }
}
